SELECT ca.ca_state AS state, ib.ib_income_band_sk AS income_band, sm.sm_type AS ship_mode, SUM(cs.cs_net_profit) AS total_sales_profit, SUM(COALESCE(cr.cr_return_amount, 0)) AS total_return_amount, (SUM(cs.cs_net_profit) - SUM(COALESCE(cr.cr_return_amount, 0))) AS net_profit_after_returns, SUM(cs.cs_ext_discount_amt) AS total_discount FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk JOIN customer_address ca ON cs.cs_bill_addr_sk = ca.ca_address_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk LEFT JOIN catalog_returns cr ON cs.cs_order_number = cr.cr_order_number AND cs.cs_item_sk = cr.cr_item_sk WHERE cs.cs_sold_date_sk BETWEEN 2450000 AND 2459999 GROUP BY ca.ca_state, ib.ib_income_band_sk, sm.sm_type HAVING SUM(cs.cs_net_profit) > 1000 ORDER BY net_profit_after_returns DESC LIMIT 20
